import{_ as a,o as r,c as i,ag as o}from"./chunks/framework.cyF4XceO.js";const f=JSON.parse('{"title":"Form Proposal workspace","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/index.md","filePath":"proposals/index.md"}'),t={name:"proposals/index.md"};function s(n,e,c,d,l,p){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="form-proposal-workspace" tabindex="-1">Form Proposal workspace <a class="header-anchor" href="#form-proposal-workspace" aria-label="Permalink to &quot;Form Proposal workspace&quot;">​</a></h1><p>This directory contains mutable design material. A proposal is never itself a package, release, maturity claim, Host Support decision, or Service Offering.</p><h2 id="current-official-family" tabindex="-1">Current official family <a class="header-anchor" href="#current-official-family" aria-label="Permalink to &quot;Current official family&quot;">​</a></h2><p>The current publisher corpus is the one versionless family <code>edge.forms.takoform.com</code>: 16 exact Experimental <code>0.x</code> Forms, with 7 Interfaces and 6 Bindings. The source roster is pinned to <a href="https://github.com/tako0614/takoform-forms/tree/3a395e4d7f9f652a942da52905857fccc41b467e" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3a395e4</code></a>. The retained Provider candidate projection is <a href="../forms/candidates/edge.forms.takoform.com/candidate-set.json"><code>forms/candidates/edge.forms.takoform.com/candidate-set.json</code></a>; it is source history, not a second publisher registry. The <a href="./edge/">Edge Platform Family proposals</a> mirror that roster and remain non-normative design notes; exact identity lives in the pinned source.</p><h2 id="deferred-candidate-families-historical-source" tabindex="-1">Deferred candidate families (historical source) <a class="header-anchor" href="#deferred-candidate-families-historical-source" aria-label="Permalink to &quot;Deferred candidate families (historical source)&quot;">​</a></h2><p>Function, Container, Table, Pull Queue, Topic, Schedule, and Vector proposals are retained historical/deferred source. They are <strong>not current Forms</strong>, do not appear in the Current navigation, and reserve no current identity:</p><ul><li><a href="./function/">Function family (historical/deferred)</a></li><li><a href="./container/">Container family (historical/deferred)</a></li><li><a href="./table/">Table family (historical/deferred)</a></li><li><a href="./queue/">Pull Queue family (historical/deferred)</a></li><li><a href="./topic/">Topic family (historical/deferred)</a></li><li><a href="./schedule/">Schedule family (historical/deferred)</a></li><li><a href="./vector/">Vector family (historical/deferred)</a></li></ul><p>Their pages remain available for source inspection, migration, and exact historical-state recovery. The released Provider <code>3.0.0</code> projection of those families is an immutable 8-family/31-resource historical record, not evidence that the publisher&#39;s current corpus has that shape. A future official-only Provider mapping for Edge16 is a next-major candidate and is not published.</p><p>The pre-family flat Proposal set and lifecycle registry were withdrawn with the pre-Beta epochs; their documents stay in git history as design provenance and reserve no public identity.</p><p>Start new design work by copying <code>TEMPLATE.md</code> into a family&#39;s subdirectory. Proposal review does not authorize publication. A withdrawn proposal is removed unless a decision record needs to retain its design history.</p><p>Before review, run the family conformance check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/standard-form-conformance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div>',12)])])}const m=a(t,[["render",s]]);export{f as __pageData,m as default};
